NOTE = [[("[Drafting note: FIG. 56 is added to the drawing set, which now comprises FIG. 1–56, one figure per sheet.]", False)]]

CLAIMS = [
 ("355.  ", "The method of claim 1, further comprising providing, to an external service interposed between an artificial-intelligence agent and a network, a read-only verification interface that receives a candidate knowledge record or its semantic fingerprint and returns a signed verdict of verified, contradicted or unknown, said verdict being determined by fingerprint lookup among certified records and, absent a match, by a query for certified records having the same subject and predicate and a conflicting value."),
 ("356.  ", "The method of claim 355, further comprising reserving a range of frame message types and a header flag of the framed transport for said external service, and accepting from said service, under a registered identity, appends to the hash-chained security record, from which a Merkle root over the entries of one session is computed and sealed as a session certificate verifiable by any party."),
 ("357.  ", "The method of claim 355, wherein said external service is registered through the agent gateway with read-only verification rights and append-only record rights, receives signed policy bundles, and observes tool calls and hashed tool result records through hooks of the tool server, and wherein said service is never permitted to write knowledge records."),
]
